import React, { useState } from "react";

const products = [
  {
    id: 1,
    category: "LUXE ESSENTIALS",
    name: "Crescent Silk Blouse",
    price: 240,
    image:
      "https://lh3.googleusercontent.com/aida-public/AB6AXuAlsit0y8Bkroi1xjhvO6tCzaJYA9wkaSG96Su74vwKKz__TmMQR0ZptAReAUmPnEWH6mU2obKag4FRgiQ-KFtYUAntXYExy57xHzxm1kAFvWVR9MMdS_SEJV0FA5-ZJwdVKscxQyAYCnTj2PxaGmHuM3mafZKplbS71fZ-wntfEtFTirwp0sHFTdTGll9f4NqV0o26U4_iXCE-mEqNcu-ebR6tbwzmUX_OSzvcha63qDt0WL9KbIBaca5ywoDg0IZg4dKvgGFo2Qg7",
  },
  {
    id: 2,
    category: "LUXE ATELIER",
    name: "Architectural Trousers",
    price: 380,
    image:
      "https://lh3.googleusercontent.com/aida-public/AB6AXuD7gPtk_yUSe4IPYp-0bj2bleQWyti73zX6SL_GEpx_rMuJ_PWoWrKrVByA3BbNTBMihKfPGtUcyRt9yy78Ha2467lgVIquaUymwhBNDd6I34e3OAzgprZbPI-8cZUQhySG_WtPMMFO4i-obzQTl1WixaV7AOWcRX0VYpPqrtmGcV6AWGqN1hKwYIqDwJtmYq7Wik2nZmWcJkv_g_GdaRe-7ypNbxfvWfXEsQzwRNImEmsc9iPAU9wbIScyjJlv8zuIORsR-2VurFwA",
  },
  {
    id: 3,
    category: "LUXE SEASONAL",
    name: "Solstice Cashmere Coat",
    price: 850,
    image:
      "https://lh3.googleusercontent.com/aida-public/AB6AXuAlvrwW8RjTiBfdptTQWkgclNy9tFc8XNhwN4ICKqrOdkqI5DmoNHEX8SUpzwWiFQoV2rzyjMGbaNgg0tfs0wQb2_MlRObVhIfoZiN_SModGW3LI5kMozcEBbp53PrCEjyOSI2F2Duq1vimXAc_lCRlUKPRRx2EIgdALiStGP2ZM0iTX4SE_HQN9LaaTWejyhcGADpFzpCikPWyW8mRpE1KqKujF6aEs9aeFaTf3NnvtsSalG7WIs0oeVKywxzutXVkBfH_f8GZq8I_",
  },
  {
    id: 4,
    category: "LUXE EVENING",
    name: "Nocturne Shift Dress",
    price: 320,
    image:
      "https://lh3.googleusercontent.com/aida-public/AB6AXuAjd1XrYOfRZj7XdAMNoKrqSYTKwwI-exeNzaBQkKDOF_KAxcpsUv-nYxdZpNSrDscH1JPq63ElUtUPQ5tMqZuvPkJZOS4THG6YSQOZok-NA-Rlo9rFAC2ZXFGvbpLc_DCJ0oOviDNPM4LYu9ibv809G-4Oav4O0Cim_OZSYZJbWfScVBOiyqpcepCSIIkR0CRmXWhq0fpsrxsEAZxW7uDJ1SuURC-m2YRNXBBX41bOt17PZW3PB3lGh9A-CkgjdJIfrKySoH_a5zC9",
  },
];

export default function ProductCatalog() {
  const [search, setSearch] = useState("");

  const filteredProducts = products.filter((p) =>
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="bg-surface text-on-surface min-h-screen">
      {/* Header */}
      <header className="fixed top-0 w-full bg-white shadow z-50">
        <div className="flex justify-between items-center h-16 px-6 max-w-7xl mx-auto">
          <span className="text-2xl font-serif italic tracking-widest">
            LUXE
          </span>
        </div>
      </header>

      <main className="pt-24 px-6 max-w-7xl mx-auto">
        {/* Search */}
        <div className="mb-8">
          <input
            type="text"
            placeholder="Search products..."
            className="w-full border-b p-3 outline-none"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        {/* Products */}
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
          {filteredProducts.map((product) => (
            <div key={product.id} className="group">
              <div className="aspect-[3/4] overflow-hidden mb-3">
                <img
                  src={product.image}
                  alt={product.name}
                  className="w-full h-full object-cover group-hover:scale-105 transition"
                />
              </div>

              <p className="text-xs text-gray-400">{product.category}</p>
              <h3 className="font-semibold">{product.name}</h3>
              <p className="text-gray-600">${product.price}</p>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}
